/// Privileged StorageService boundary that mints a client restricted to one directory
/// below a system volume. The returned channel preserves normal `volume` operations,
/// but rejects paths outside the granted directory and cannot mint a broader client.
// interface `volume-admin` over a channel: opcodes, a Service trait + dispatch, and a Client.
pub mod volume_admin {
	use super::*;
	use crate::codec::{Reader, Sink, SliceWriter, Transport, VecWriter};
	use alloc::vec::Vec;

	pub const OP_OPEN_DIRECTORY: u16 = 1;

	pub trait Service {
		fn open_directory(&mut self, path: String) -> Result<u64, Error>;
	}

	pub fn dispatch<S: Service>(service: &mut S, request: &[u8], request_handles: &mut Handles, out: &mut [u8], reply_handles: &mut Handles) -> Option<usize> {
		let mut reader = Reader::with_handle_list(request, request_handles);
		let r = &mut reader;
		let op = r.u16()?;
		let corr = r.u32()?;
		let mut writer = SliceWriter::new(out);
		if op == PROTOCOL_INFO_OP {
			let w = &mut writer;
			w.u32(corr)?;
			w.bytes_lp(b"liber:storage")?;
			w.u32(1)?;
			match Handles::try_from_slice(writer.handles()) {
				Some(taken) => *reply_handles = taken,
				None => return None,
			}
			return Some(writer.pos());
		}
		match op {
			OP_OPEN_DIRECTORY => {
				let path = r.string_lp()?;
				r.finish()?;
				request_handles.clear();
				let result = service.open_directory(path);
				let encoded: Option<()> = (|| {
					let w = &mut writer;
					w.u32(corr)?;
					match &result {
						Ok(v44) => {
							w.u8(1)?;
							w.set_handle(*v44)?;
							w.u32(0)?;
						}
						Err(v45) => {
							w.u8(0)?;
							v45.write(w)?;
						}
					}
					Some(())
				})();
				if encoded.is_none() {
					if writer.has_handle() {
						match Handles::try_from_slice(writer.handles()) {
							Some(taken) => *reply_handles = taken,
							None => {}
						}
						return None;
					}
					// the reply outgrew the caller's buffer: replace it with a typed
					// error, so the client sees a failure instead of hanging.
					writer.reset();
					let w = &mut writer;
					w.u32(corr)?;
					w.u8(0)?;
					Error::Again.write(w)?;
				}
			}
			_ => return None,
		}
		match Handles::try_from_slice(writer.handles()) {
			Some(taken) => *reply_handles = taken,
			None => return None,
		}
		Some(writer.pos())
	}

	pub struct Client<T: Transport> {
		transport: T,
		corr: u32,
	}

	impl<T: Transport> Client<T> {
		pub fn new(transport: T) -> Client<T> {
			Client { transport, corr: 0 }
		}
		pub fn into_transport(self) -> T {
			self.transport
		}
		fn next_corr(&mut self) -> u32 {
			let c = self.corr;
			self.corr = self.corr.wrapping_add(1);
			c
		}
		pub fn protocol_info(&mut self) -> Option<(String, u32)> {
			let corr = self.next_corr();
			let mut writer = VecWriter::new();
			let w = &mut writer;
			w.u16(PROTOCOL_INFO_OP)?;
			w.u32(corr)?;
			let request = writer.into_inner();
			let mut reply_handles = Handles::new();
			let reply = self.transport.call(&request, &[], &mut reply_handles)?;
			if !reply_handles.is_empty() {
				self.transport.discard_handles(reply_handles.as_slice());
				return None;
			}
			let mut reader = Reader::new(&reply);
			let r = &mut reader;
			if r.u32()? != corr {
				return None;
			}
			let package = r.string_lp()?;
			let version = r.u32()?;
			Some((package, version))
		}
		pub fn open_directory(&mut self, path: &str) -> Option<Result<u64, Error>> {
			let corr = self.next_corr();
			let mut writer = VecWriter::new();
			let w = &mut writer;
			w.u16(OP_OPEN_DIRECTORY)?;
			w.u32(corr)?;
			w.bytes_lp(path.as_bytes())?;
			let request_handles = Handles::try_from_slice(writer.handles())?;
			let request = writer.into_inner();
			let mut reply_handles = Handles::new();
			let reply = self.transport.call(&request, request_handles.as_slice(), &mut reply_handles)?;
			let mut reader = Reader::with_handle_list(&reply, &reply_handles);
			let decoded = (|| {
				let r = &mut reader;
				if r.u32()? != corr {
					return None;
				}
				let value = if r.tag()? {
					Ok({
						let _ = r.u32()?;
						r.take_handle()?
					})
				} else {
					Err(Error::read(r)?)
				};
				r.finish()?;
				Some(value)
			})();
			if decoded.is_none() {
				self.transport.discard_handles(reply_handles.as_slice());
				return None;
			}
			decoded
		}
	}

	#[cfg(feature = "channel-client-impl")]
	#[inline(never)]
	#[unsafe(export_name = "liber_channel_impl_liber_storage_volume_admin_open_directory")]
	fn channel_invoke_open_directory(chan: u64, path: &str) -> Option<Result<u64, Error>> {
		let mut client = Client::new(ipc_client::ChannelTransport { chan });
		client.open_directory(path)
	}
}

impl OpenOpts {
	pub fn to_json(&self) -> String {
		let mut s = String::new();
		self.to_json_into(&mut s);
		s
	}
	pub fn to_text(&self) -> String {
		let mut s = String::new();
		self.to_text_into(&mut s);
		s
	}
	pub fn to_cbor(&self) -> Vec<u8> {
		let mut v = Vec::new();
		self.to_cbor_into(&mut v);
		v
	}
	pub(crate) fn to_json_into(&self, out: &mut String) {
		out.push('{');
		out.push_str("\"path\":");
		crate::codec::json_escape(&self.path, out);
		out.push(',');
		out.push_str("\"write\":");
		if self.write {
			out.push_str("true");
		} else {
			out.push_str("false");
		}
		out.push(',');
		out.push_str("\"create\":");
		if self.create {
			out.push_str("true");
		} else {
			out.push_str("false");
		}
		out.push('}');
	}
	pub(crate) fn to_text_into(&self, out: &mut String) {
		out.push('{');
		out.push_str("path=");
		out.push_str(&self.path);
		out.push_str(", ");
		out.push_str("write=");
		if self.write {
			out.push_str("true");
		} else {
			out.push_str("false");
		}
		out.push_str(", ");
		out.push_str("create=");
		if self.create {
			out.push_str("true");
		} else {
			out.push_str("false");
		}
		out.push('}');
	}
	pub(crate) fn to_cbor_into(&self, out: &mut Vec<u8>) {
		crate::codec::cbor::map(out, 3);
		crate::codec::cbor::text(out, "path");
		crate::codec::cbor::text(out, &self.path);
		crate::codec::cbor::text(out, "write");
		crate::codec::cbor::boolean(out, self.write);
		crate::codec::cbor::text(out, "create");
		crate::codec::cbor::boolean(out, self.create);
	}
}

